arduino.setup:
// Motor Control Setup
void setup() {
  pinMode([[helper:driver:ENA|ENB]], OUTPUT);
  pinMode([[helper:driver:IN1|IN3]], OUTPUT);
  pinMode([[helper:driver:IN2|IN4]], OUTPUT);
  analogWrite([[helper:driver:ENA|ENB]], 200);
}

arduino.loop:
void loop() {
  digitalWrite([[helper:driver:IN1|IN3]], HIGH); digitalWrite([[helper:driver:IN2|IN4]], LOW);
  delay(2000);
  digitalWrite([[helper:driver:IN1|IN3]], LOW); digitalWrite([[helper:driver:IN2|IN4]], LOW);
  delay(500);
}
